import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.BXzK3EA4.js";const l="/recipe_anatomy.png",g=JSON.parse('{"title":"Day 8: Writing Recipes & C Applications","description":"","frontmatter":{},"headers":[],"relativePath":"day8-writing-recipes-and-c-apps.md","filePath":"day8-writing-recipes-and-c-apps.md"}'),n={name:"day8-writing-recipes-and-c-apps.md"};function o(r,e,d,c,p,h){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="day-8-writing-recipes-c-applications" tabindex="-1">Day 8: Writing Recipes &amp; C Applications <a class="header-anchor" href="#day-8-writing-recipes-c-applications" aria-label="Permalink to &quot;Day 8: Writing Recipes &amp; C Applications&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the anatomy of a Yocto <code>.bb</code> recipe and its essential variables</li><li>Write a custom recipe to cross-compile a local C application from scratch</li><li>Differentiate between <code>${WORKDIR}</code>, <code>${S}</code>, and <code>${D}</code> directories</li><li>Utilize <code>do_compile</code> and <code>do_install</code> tasks to build and stage binaries</li><li>Integrate your compiled application into a custom image</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day7-custom-image-recipes-and-features.html">Day 7: Custom Image Recipes &amp; Image Features</a></li></ul></div><hr><h2 id="_1-anatomy-of-a-bitbake-recipe" tabindex="-1">1. Anatomy of a BitBake Recipe <a class="header-anchor" href="#_1-anatomy-of-a-bitbake-recipe" aria-label="Permalink to &quot;1. Anatomy of a BitBake Recipe&quot;">​</a></h2><p>A recipe (<code>.bb</code> file) is the fundamental unit of the Yocto build system. It instructs BitBake on how to fetch, patch, compile, and package a specific software component.</p><p><img src="'+l+`" alt="Recipe Anatomy"></p><h3 id="the-essential-variables" tabindex="-1">The Essential Variables <a class="header-anchor" href="#the-essential-variables" aria-label="Permalink to &quot;The Essential Variables&quot;">​</a></h3><p>Every recipe must contain a core set of metadata variables to function correctly:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>SUMMARY</code></td><td>A short, one-line description of the software.</td></tr><tr><td><code>DESCRIPTION</code></td><td>A longer, detailed description.</td></tr><tr><td><code>LICENSE</code></td><td>The open-source license (e.g., <code>&quot;MIT&quot;</code>, <code>&quot;GPL-2.0-only&quot;</code>).</td></tr><tr><td><code>LIC_FILES_CHKSUM</code></td><td>A cryptographic checksum of the license text file. BitBake checks this to ensure the license hasn&#39;t changed without you knowing.</td></tr><tr><td><code>SRC_URI</code></td><td>A space-separated list of source files (tarballs, git repos, or local files) to fetch.</td></tr><tr><td><code>S</code></td><td>The Source directory. Where the extracted source code lives (default is <code>\${WORKDIR}/\${BP}</code>).</td></tr></tbody></table><hr><h2 id="_2-compiling-a-local-c-application" tabindex="-1">2. Compiling a Local C Application <a class="header-anchor" href="#_2-compiling-a-local-c-application" aria-label="Permalink to &quot;2. Compiling a Local C Application&quot;">​</a></h2><p>Let&#39;s walk through creating a recipe that compiles a simple &quot;Hello World&quot; C program. We will store the <code>.c</code> file alongside the recipe.</p><h3 id="step-1-create-the-recipe-directory-structure" tabindex="-1">Step 1: Create the Recipe Directory Structure <a class="header-anchor" href="#step-1-create-the-recipe-directory-structure" aria-label="Permalink to &quot;Step 1: Create the Recipe Directory Structure&quot;">​</a></h3><p>Inside your <code>meta-myproject</code> layer, create a new directory for your recipe:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-myproject/recipes-example/helloworld/files</span></span></code></pre></div><h3 id="step-2-create-the-source-code" tabindex="-1">Step 2: Create the Source Code <a class="header-anchor" href="#step-2-create-the-source-code" aria-label="Permalink to &quot;Step 2: Create the Source Code&quot;">​</a></h3><p>Create <code>helloworld.c</code> inside the <code>files/</code> subdirectory:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// meta-myproject/recipes-example/helloworld/files/helloworld.c</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;stdio.h&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello from Yocto Embedded Linux!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="step-3-write-the-recipe" tabindex="-1">Step 3: Write the Recipe <a class="header-anchor" href="#step-3-write-the-recipe" aria-label="Permalink to &quot;Step 3: Write the Recipe&quot;">​</a></h3><p>Create <code>helloworld_1.0.bb</code> inside <code>recipes-example/helloworld/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUMMARY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;A simple Hello World C application&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LICENSE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MIT&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LIC_FILES_CHKSUM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file://\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">COMMON_LICENSE_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/MIT;md5=0835ade698e0bcf8506ecda2f7b4f302&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Point to our local C file. The file:// fetcher looks in the &#39;files/&#39; subdirectory.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file://helloworld.c&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Because we are compiling a single local file, there is no extracted tarball directory.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># We must tell BitBake that our source directory IS the work directory.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WORKDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # \${CC} contains the cross-compiler (e.g. arm-linux-gnueabihf-gcc)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # \${CFLAGS} and \${LDFLAGS} contain target-specific optimization flags</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    \${CC} \${CFLAGS} \${LDFLAGS} </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">helloworld.c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 1. Create the /usr/bin directory inside the staging area (\${D})</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${D}\${bindir}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 2. Copy the compiled binary into the staging /usr/bin directory</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # -m 0755 sets the executable file permissions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${D}\${bindir}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="_3-understanding-the-working-directories" tabindex="-1">3. Understanding the Working Directories <a class="header-anchor" href="#_3-understanding-the-working-directories" aria-label="Permalink to &quot;3. Understanding the Working Directories&quot;">​</a></h2><p>To write recipes, you must understand where BitBake is executing your shell commands.</p><table tabindex="0"><thead><tr><th>Path Variable</th><th>Description</th><th>Typical Value</th></tr></thead><tbody><tr><td><code>\${WORKDIR}</code></td><td>The isolated sandbox directory for this specific recipe build.</td><td><code>tmp/work/cortexa8.../helloworld/1.0-r0/</code></td></tr><tr><td><code>\${S}</code></td><td>The directory where the unpacked source code lives.</td><td><code>.../1.0-r0/git/</code> or <code>.../1.0-r0/</code></td></tr><tr><td><code>\${D}</code></td><td>The &quot;Destination&quot; staging directory. This mimics the target device&#39;s root filesystem structure. Everything installed here is later packaged into IPKs/RPMs.</td><td><code>.../1.0-r0/image/</code></td></tr><tr><td><code>\${bindir}</code></td><td>The standard binary directory path.</td><td><code>/usr/bin</code></td></tr><tr><td><code>\${sysconfdir}</code></td><td>The standard configuration directory path.</td><td><code>/etc</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">DO NOT USE HOST PATHS</p><p>Never hardcode absolute paths like <code>/usr/bin</code> in your <code>do_install</code> task. Always use variables like <code>\${bindir}</code>. Yocto must relocate paths during the build process; hardcoded paths will cause the package to fail QA checks.</p></div><hr><h2 id="_4-building-and-deploying" tabindex="-1">4. Building and Deploying <a class="header-anchor" href="#_4-building-and-deploying" aria-label="Permalink to &quot;4. Building and Deploying&quot;">​</a></h2><p>Now that the recipe is written, you can build it in isolation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld</span></span></code></pre></div><p>To add this application to your target board, add the recipe name (<code>helloworld</code>) to your custom image recipe (<code>my-custom-image.bb</code>) from Day 7:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In meta-myproject/recipes-core/images/my-custom-image.bb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMAGE_INSTALL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;helloworld&quot;</span></span></code></pre></div><p>Rebuild the image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-custom-image</span></span></code></pre></div><p>Boot the image using QEMU (<code>runqemu qemuarm nographic</code>), log in as root, and execute <code>helloworld</code>. You should see your print statement!</p><hr><h2 id="_5-hands-on-lab-exercises" tabindex="-1">5. Hands-On Lab Exercises <a class="header-anchor" href="#_5-hands-on-lab-exercises" aria-label="Permalink to &quot;5. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 8.1: Recipe Environment Inspection</p><p>BitBake provides a way to see exactly how all those <code>\${...}</code> variables evaluate for a specific recipe.</p><ol><li>Run <code>bitbake -e helloworld | grep ^WORKDIR=</code> to see the exact path of the sandbox.</li><li>Run <code>bitbake -e helloworld | grep ^CC=</code> to see the massive, complicated cross-compiler invocation string that Yocto abstracts away for you.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 8.2: Inspecting the Output Packages</p><ol><li>Navigate to the <code>build/tmp/work/</code> directory and find the <code>helloworld</code> folder.</li><li>Look inside the <code>packages-split/</code> subdirectory.</li><li>You will see several folders: <code>helloworld</code>, <code>helloworld-dev</code>, <code>helloworld-dbg</code>. This is where <code>do_package</code> splits the contents of <code>\${D}</code>. Look inside <code>helloworld/usr/bin/</code> to verify your binary is there.</li></ol></div><hr><h2 id="_6-further-reading" tabindex="-1">6. Further Reading <a class="header-anchor" href="#_6-further-reading" aria-label="Permalink to &quot;6. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Writing a New Recipe</td><td><a href="https://docs.yoctoproject.org/dev-manual/new-recipe.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/new-recipe.html</a></td></tr><tr><td>Standard Directory Variables</td><td><a href="https://docs.yoctoproject.org/ref-manual/variables.html#term-bindir" target="_blank" rel="noreferrer">docs.yoctoproject.org/ref-manual/variables.html#term-bindir</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day7-custom-image-recipes-and-features">← Day 7: Custom Image Recipes &amp; Features</a><a href="/day9-build-logs-debugging-makefiles">Day 9: Build Logs &amp; Makefiles →</a></div>`,45)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
